 "content": "from collections import deque

def _canonical(shape):
    pts = list(shape)
    forms = []
    for reflect in (1, -1):
        for k in range(4):
            transformed = []
            for r, c in pts:
                x, y = r, c * reflect
                for _ in range(k):
                    x, y = y, -x
                transformed.append((x, y))
            mr = min(x for x, y in transformed)
            mc = min(y for x, y in transformed)
            forms.append(tuple(sorted((x-mr, y-mc) for x, y in transformed)))
    return min(forms)

def transform(grid):
    h, wfull = len(grid), len(grid[0])
    bg = grid[0][0]
    width = 0
    while width < wfull and grid[0][width] == bg:
        width += 1
    # Full-width bars across the left-hand framed area mark the panels.
    bars = [r for r in range(h) if all(grid[r][c] == bg for c in range(width))]
    panels = [(a, b) for a, b in zip(bars, bars[1:]) if b > a+1]
    # Find connected colored objects in the right-hand area.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(width+1, wfull):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and width+1 <= ny < wfull and (nx,ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx,ny)); q.append((nx,ny))
            r0=min(x for x,y in cells); c0=min(y for x,y in cells)
            objects.append((color, _canonical((x-r0,y-c0) for x,y in cells)))
    out = [row[:width] for row in grid]
    remaining = list(objects)
    for a,b in panels:
        mask={(r-a,c-1) for r in range(a+1,b) for c in range(1,width-1) if grid[r][c] == 0}
        key=_canonical(mask)
        match=next((i for i,(_,shape) in enumerate(remaining) if shape == key),None)
        if match is None:
            raise ValueError('No matching object for panel')
        color,_=remaining.pop(match)
        for r in range(a+1,b):
            for c in range(1,width-1):
                if grid[r][c] == 0:
                    out[r][c]=color
    return out
